entries[48768] = { ["name"] = "Kabummbomben", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Werft die Kabummbomben bis zu 5 Meter weit, um eine Kaja'mitablagerung in Stücke zu sprengen. Dann müsst Ihr nur noch die übrigen Brocken einsammeln. Wenn Ihr schon dabei seid, könnt Ihr die Kabummbomben auch benutzen, um diese renitenten rebellischen Trolle zu betäuben! (5 Sek. Abklingzeit)" }
