entries[48933] = { ["name"] = "Wurmlochgenerator: Nordend", ["text"] = "Wird bei Benutzung gebunden\nSpielzeug\nBenutzen: Erschafft ein instabiles Wurmloch, das der Ingenieur verwenden kann, um Nordend zu bereisen. Hält 1 Min. lang an. (4 Std. Abklingzeit)\nBenötigt Ingenieurskunst von Nordend (40)\n\"Die Dimensionsfaltung ist noch von keinem Forschungsbereich vollständig verstanden worden. Bereithaltung von Fallschirm und medizinischer Notversorgung ist angeraten!\"\nVerkaufspreis:" }
