entries[49040] = { ["name"] = "Jeeves", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Erbittet die Anwesenheit von Jeeves, dem perfekten robotischen Gentleman-Butler, der Euch 10 Min. lang zu Diensten sein wird.\n\nJeeves kann sehr fähigen Ingenieuren Zugriff auf die Bank gewähren und jedem bei so alltäglichen Geschäften wie Verkauf, Ankauf und Reparaturen behilflich sein. (1 Stunde Abklingzeit)\nBenötigt Ingenieurskunst von Nordend (75)" }
