entries[49044] = { ["name"] = "Schnelles Ross der Allianz", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenötigt eine Allianz-Rasse\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört ein reitbares schnelles Ross der Allianz oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Einige der schnellsten Reittiere des Argentumkreuzzugs wurden an jene Mitglieder der Allianz verliehen, die im Turnier von Eiskrone besonders gut abgeschnitten haben.\"\nKlassisch" }
entries[49046] = { ["name"] = "Schneller Wolf der Horde", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenötigt eine Horde-Rasse\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört einen reitbaren schnellen Wolf der Horde oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Einige der schnellsten Reittiere des Argentumkreuzzugs wurden an jene Mitglieder der Horde verliehen, die im Turnier von Eiskrone besonders gut abgeschnitten haben.\"\nKlassisch" }
entries[49050] = { ["name"] = "Bauplan: Jeeves", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch die Herstellung des robotischen Butlers Jeeves.\nBenötigt Ingenieurskunst von Nordend (75)\nVerkaufspreis:\nJeeves\nWird beim Aufheben gebunden\nBenutzen: Erbittet die Anwesenheit von Jeeves, dem perfekten robotischen Gentleman-Butler, der Euch 10 Min. lang zu Diensten sein wird.\n\nJeeves kann sehr fähigen Ingenieuren Zugriff auf die Bank gewähren und jedem bei so alltäglichen Geschäften wie Verkauf, Ankauf und Reparaturen behilflich sein. (1 Stunde Abklingzeit)\nBenötigt Ingenieurskunst von Nordend (75)\nBenötigt Feldreparaturbot 74A (2), Feldreparaturbot 110G (10), Konstruktionsset: Schrottboter (20), Titanstahlbarren (8), Königsbernstein (2), Eine Handvoll Kobaltbolzen (30)" }
