entries[49279] = { ["name"] = "Omas gute Kleider", ["text"] = "Questgegenstand\n\"Ihr seid nicht ganz sicher, aber sie sehen genauso aus wie die, die sie schon trug.\"" }
entries[49280] = { ["name"] = "Leinengebundenes Buch", ["text"] = "Questgegenstand\n\"Bei diesem Buch scheint es sich um eine feurige Liebesgeschichte zu handeln. Auf dem Buchdeckel ist eine idyllische Szene zu sehen, die einen muskulösen blonden Mann und eine junge Frau in einem engen Mieder zeigt.\"" }
entries[49281] = { ["name"] = "Felix die Katze", ["text"] = "Questgegenstand\n\"Ein wenig durchgeschüttelt, aber in gutem Zustand... den Umständen entsprechend.\"" }
entries[49282] = { ["name"] = "Großer Kampfbär", ["text"] = "Einzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört einen reitbaren großen Kampfbären oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Es ist groß und zum Kämpfen bereit und es ist ein Bär. Was will man denn sonst noch von einem Reittier?\"\nVerkäufer:\nLandro Fernblick\nOrt:\nBeutebucht" }
entries[49283] = { ["name"] = "Zügel des Spektraltigers", ["text"] = "Einzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört einen reitbaren Spektraltiger und gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Wie es sich für einen Goblin gehört, hat Landro Fernblick den Vertrieb dieser geheimnisvollen körperlosen Reittiere fest im Klammergriff.\"\nVerkäufer:\nLandro Fernblick\nOrt:\nBeutebucht" }
entries[49284] = { ["name"] = "Zügel des schnellen Spektraltigers", ["text"] = "Einzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört einen reitbaren schnellen Spektraltiger oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Die Historiker meinen, dass diese körperlosen Bestien erschaffen wurden, als Draenor explodierte und Energien entfesselte, die Flora und Fauna der Welt beeinflussten.\"\nVerkäufer:\nLandro Fernblick\nOrt:\nBeutebucht" }
entries[49285] = { ["name"] = "X-51 Netherrakete", ["text"] = "Einzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nEine Reitrakete! Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Ursprünglich als Beschleunigung für eine deutlich größere Rakete entwickelt, ermöglicht die X-51 den bestmöglichen Schub für einen einzelnen Passagier.\"\nVerkäufer:\nLandro Fernblick\nOrt:\nBeutebucht" }
entries[49286] = { ["name"] = "X-51 Netherrakete X-TREM", ["text"] = "Einzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nEine X-TREME Reitrakete! Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Die Geschwindigkeit und der unverkennbare Still gleichen die fehlenden Sicherheitsmerkmale locker aus. Nichts für nervöse Gemüter.\"\nVerkäufer:\nLandro Fernblick\nOrt:\nBeutebucht" }
entries[49287] = { ["name"] = "Tuskarrdrachen", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört.\nMit Rechtsklick Euren Drachen beschwören oder wieder freigeben.\n80 ( 80)" }
entries[49288] = { ["name"] = "Pfeife des kleinen elfenbeinfarbenen Raptors", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenötigt eine Horde-Rasse\nBenutzen: Beschwört einen reitbaren kleinen elfenbeinfarbenen Raptor oder gibt ihn wieder frei. Die Geschwindigkeit dieses Reittieres ist von Eurer Reitfertigkeit abhängig." }
entries[49289] = { ["name"] = "Zaumzeug des kleinen Schimmels", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenötigt eine Allianz-Rasse\nBenutzen: Beschwört einen reitbaren kleinen Schimmel oder gibt ihn wieder frei. Die Geschwindigkeit dieses Reittieres ist von Eurer Reitfertigkeit abhängig." }
entries[49290] = { ["name"] = "Magisches Hühnerei", ["text"] = "Einzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört einen reitbaren magischen Hahn oder gibt ihn wieder frei. Nein, ehrlich!\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"In den Händen eines Genies kann Magie unglaubliche Wunder bewirken. In den Händen eines Idioten führt sie zu einem riesigen Gockel.\"\nVerkäufer:\nLandro Fernblick\nOrt:\nBeutebucht" }
