entries[49298] = { ["name"] = "Glitzernde Magierklinge des Azurlieds", ["text"] = "Wird beim Aufheben gebunden\nEinhändig Schwert\n2 - 4 Schaden Geschwindigkeit 2.60\n(1.2 Schaden pro Sekunde)\n+12 Intelligenz\n+3 Ausdauer\nErhöht Eure kritische Trefferwertung um + 3.\nErhöht Eure Tempowertung um + 2.\nHaltbarkeit 110 / 110\nVerkaufspreis:" }
